CREATE OR REPLACE FUNCTION public.fn_ca_lock_settlement_lane_for_finish(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_held text := COALESCE(current_setting('ca.finish_lane_tournament', true), '');
  v_held_scope text := COALESCE(current_setting('ca.finish_lane_scope', true), '');
  -- Unknown until the row proves it is a plain tournament: the whole lane.
  v_satellite boolean := true;
  v_scope text;
BEGIN
  -- Re-entry: this transaction already holds a finish lane. Every key below
  -- is already held by this backend, so nothing waits; a second tournament
  -- is refused, a transaction never holds two tournaments' lanes. (Inside a
  -- satellite finish or a sweep, F is held exclusively by this backend, so F
  -- shared is granted at once and no scope key is named.)
  IF v_held <> '' THEN
    IF p_tournament_id IS NOT NULL AND v_held <> p_tournament_id::text THEN
      RAISE EXCEPTION 'finish lane is held for tournament %, refused for %',
        v_held, p_tournament_id USING ERRCODE = '55000';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1', 0));
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-finish-lane:v1', 0));
    IF v_held_scope <> '' THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_held_scope, 0));
    END IF;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1:' || v_held, 0));
    RETURN;
  END IF;

  -- Resolve the tournament before any lock. variant, tournament_type and the
  -- satellite target are fixed for the life of the row, so reading them
  -- unlocked gives the answer reading them under the lane would. The bank
  -- scope is the host club's union, else the host club; the finish itself
  -- refuses (40001) if the club changes union before it holds the banks.
  IF p_tournament_id IS NOT NULL THEN
    SELECT (lower(COALESCE(t.variant::text, '')) = 'satellite'
            OR upper(COALESCE(t.tournament_type::text, '')) = 'SATELLITE'
            OR t.satellite_target_id IS NOT NULL
            OR t.satellite_target IS NOT NULL),
           COALESCE(c.union_id::text, t.club_id::text, '')
      INTO v_satellite, v_scope
      FROM public.tournaments t
      LEFT JOIN public.clubs c ON c.id = t.club_id
     WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      v_satellite := true;
    END IF;
  END IF;

  -- A satellite finish writes the target tournament's rows, and an unknown
  -- tournament cannot be scoped: the whole lane, as it always was.
  IF v_satellite OR COALESCE(v_scope, '') = '' THEN
    PERFORM public.fn_ca_lock_settlement_lane_global();
    RETURN;
  END IF;

  -- G SHARED: waits for, and excludes, the rare global authorities (G
  -- exclusive) and nothing else.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  -- F SHARED: satellite finishes and sweeps hold F exclusively and still
  -- exclude every ordinary finish; ordinary finishes no longer exclude
  -- each other platform-wide.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-finish-lane:v1', 0));
  -- F(scope) EXCLUSIVE: one finish at a time per bank scope, so finishes
  -- that share a club wallet, union bank, club treasury or the players'
  -- wallets in those clubs keep the order they had under F exclusive.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_scope, 0));
  -- T(id) EXCLUSIVE: this tournament's hands (T shared) and rolling
  -- authorities (T exclusive) wait for the finish, and the proof-of-
  -- authority guards read it as this backend's authority over the rows.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || p_tournament_id::text, 0));
  -- The rest of this transaction re-enters this lane through
  -- fn_ca_lock_settlement_lane_global; transaction-local, gone at commit.
  PERFORM set_config('ca.finish_lane_scope', v_scope, true);
  PERFORM set_config('ca.finish_lane_tournament', p_tournament_id::text, true);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_club_union_context(p_club_id uuid)
 RETURNS TABLE(own_union_id uuid, member_union_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_union boolean;
  v_union_id uuid;
  v_own      uuid;
BEGIN
  own_union_id := NULL;
  member_union_id := NULL;

  IF p_club_id IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT COALESCE(c.is_union, false), c.union_id
    INTO v_is_union, v_union_id
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_is_union OR v_union_id = p_club_id
     OR EXISTS (SELECT 1 FROM unions u WHERE u.id = p_club_id) THEN
    v_own := p_club_id;
    v_union_id := NULL;
  END IF;

  IF v_own IS NULL AND v_union_id IS NULL THEN
    SELECT uc.union_id INTO v_union_id
      FROM union_clubs uc
     WHERE uc.club_id = p_club_id
       AND uc.union_id <> p_club_id
     LIMIT 1;
  END IF;

  own_union_id := v_own;
  member_union_id := v_union_id;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_defer_accounting_tournament_fees(p_tournament_id uuid, p_recognized_at timestamp with time zone, p_bank_club_id uuid, p_union_id uuid, p_union_wallet_transaction_id uuid, p_bank_journal_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE net_fee numeric;fp text;proof jsonb;plan jsonb;prior record;BEGIN
 IF p_recognized_at IS DISTINCT FROM transaction_timestamp() OR p_reason IS NULL
  OR p_reason NOT IN('tournament_fee_sources_require_reconciliation','accounting_terms_not_observed','accounting_terms_not_active','tournament_fee_not_captured_by_original_producer') THEN
  RAISE EXCEPTION 'tournament_fee_deferral_reason_invalid' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament
   AND (r.rake_amount IS NULL OR r.rake_amount<>round(r.rake_amount,2) OR r.rake_amount::text IN('NaN','Infinity','-Infinity'))) THEN
  RAISE EXCEPTION 'tournament_fee_source_invalid' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(sum(rake_amount),0),md5(COALESCE(string_agg(public.fn_accounting_tournament_fee_fingerprint(r),':' ORDER BY id),'')) INTO net_fee,fp
  FROM public.rake_records r WHERE tournament_id=p_tournament_id AND is_tournament;
 -- Historical deferred receipts stay readable; no new positive fee may use
 -- deferral to commit banking without complete attribution. Zero-fee
 -- cancellation evidence remains available to its existing authority.
 IF net_fee>0 THEN RAISE EXCEPTION 'tournament_fee_positive_deferral_retired' USING ERRCODE='P0404'; END IF;
 proof:=public.fn_accounting_tournament_bank_proof(p_tournament_id,p_recognized_at,p_bank_club_id,p_union_id,net_fee,p_union_wallet_transaction_id,p_bank_journal_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_recognition:'||p_tournament_id::text,0));
 SELECT * INTO prior FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=p_tournament_id;
 IF FOUND THEN
  IF prior.status IS DISTINCT FROM 'banked_accrual_deferred' OR prior.source_fingerprint IS DISTINCT FROM fp OR prior.net_rake IS DISTINCT FROM net_fee THEN
   RAISE EXCEPTION 'tournament_fee_recognition_conflict' USING ERRCODE='23514'; END IF;
  RETURN prior.plan||jsonb_build_object('replayed',true);
 END IF;
 plan:=proof||jsonb_build_object('accounting_version',2,'tournament_id',p_tournament_id,'status','banked_accrual_deferred',
  'reason',p_reason,'source_fingerprint',fp,'net_fee',net_fee,'payable',false,'commission_rows',0,'attributed_users',0,'recognized_source_count',0);
 INSERT INTO public.accounting_tournament_fee_recognitions(tournament_id,recognized_at,status,net_rake,union_id,bank_club_id,
  union_wallet_transaction_id,bank_journal_id,source_fingerprint,plan)
 VALUES(p_tournament_id,p_recognized_at,'banked_accrual_deferred',net_fee,p_union_id,p_bank_club_id,p_union_wallet_transaction_id,p_bank_journal_id,fp,plan);
 RETURN plan||jsonb_build_object('replayed',false);
END$function$

CREATE OR REPLACE FUNCTION public.fn_is_platform_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  RETURN v_role IN ('admin', 'superadmin', 'god');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_log_admin_action(p_admin_user_id uuid, p_action text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
  v_role text;
BEGIN
  IF p_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'admin_user_id required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_action IS NULL OR length(trim(p_action)) = 0 THEN
    RAISE EXCEPTION 'action required' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = p_admin_user_id;

  INSERT INTO public.admin_audit_log (
    admin_user_id, action, target_type, target_id,
    details, before_state, after_state,
    ip_address, user_agent, actor_role, request_id
  ) VALUES (
    p_admin_user_id, p_action, p_target_type, p_target_id,
    COALESCE(p_details, '{}'::jsonb), p_before_state, p_after_state,
    p_ip_address, p_user_agent, v_role, p_request_id
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_release(p_custody_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner uuid;
  v_c public.poker_diamond_custody%ROWTYPE;
  v_prev public.poker_diamond_movements%ROWTYPE;
  v_request jsonb;
  v_credit jsonb;
  v_receipt jsonb;
  v_lot record;
  v_debt_journal uuid;
BEGIN
  IF p_custody_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_diamond_release' USING ERRCODE = '22023';
  END IF;

  SELECT user_id INTO v_owner
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_custody_not_found';
  END IF;

  -- The wallet always locks before its custody, exactly as reserve does.
  PERFORM id FROM public.profiles WHERE id = v_owner FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;
  SELECT * INTO v_c
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id
   FOR UPDATE;

  v_request := jsonb_build_object(
    'action', 'release',
    'custody_id', p_custody_id,
    'user_id', v_owner
  );

  SELECT * INTO v_prev
    FROM public.poker_diamond_movements
   WHERE request_id = p_request_id;
  IF FOUND THEN
    IF v_prev.request <> v_request THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN v_prev.receipt;
  END IF;

  IF v_c.state = 'released' THEN
    RAISE EXCEPTION 'diamond_custody_already_released';
  END IF;
  -- A DIAMOND TOURNAMENT ENTRY GOES HOME ONLY THROUGH ITS REFUND AUTHORITY
  -- (Phase 8). fn_poker_diamond_tournament_refund names this row in a
  -- transaction-local setting for the one call it makes; any other caller,
  -- service role included, is refused. An entry in play is never releasable.
  IF v_c.purpose = 'tournament_entry'
     AND current_setting('app.poker_diamond_tournament_release', true) IS DISTINCT FROM p_custody_id::text THEN
    RAISE EXCEPTION 'diamond_tournament_entry_requires_refund_authority' USING ERRCODE = '42501';
  END IF;
  -- An ACTIVE tournament entry (activated by the entry door, as the seat
  -- guards P0810-P0812 require) is released whole by its refund authority;
  -- the settlement test below is the cash seat's and stays the cash seat's.
  IF v_c.state <> 'reserved' AND v_c.purpose <> 'tournament_entry' THEN
    IF v_c.state <> 'active' OR v_c.purpose <> 'cash_seat'
       OR v_c.occupancy_id IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_c.seat_id AND s.joined_at=v_c.seat_joined_at
            AND s.occupancy_id=v_c.occupancy_id AND s.user_id=v_c.user_id
            AND s.table_id=v_c.target_id AND s.left_at IS NOT NULL
            AND s.stack=v_c.balance) THEN
      RAISE EXCEPTION 'diamond_custody_requires_settlement';
    END IF;
  END IF;

  FOR v_lot IN
    SELECT l.id, r.amount-r.consumed AS amount
      FROM public.poker_diamond_lot_reservations r
      JOIN public.diamond_purchase_lots l ON l.id = r.lot_id
     WHERE r.custody_id = p_custody_id
       AND r.released_at IS NULL
     ORDER BY l.created_at, l.id
     FOR UPDATE OF l
  LOOP
    UPDATE public.diamond_purchase_lots
       SET arena_reserved = arena_reserved - v_lot.amount
     WHERE id = v_lot.id;
  END LOOP;

  UPDATE public.poker_diamond_lot_reservations
     SET released_at = now()
   WHERE custody_id = p_custody_id
     AND released_at IS NULL;

  IF v_c.balance > 0 THEN
  v_credit := public.add_diamonds_to_balance(
    v_owner,
    v_c.balance::integer,
    'arena_withdraw',
    'Released Poker Arena reservation',
    'poker-release:' || p_custody_id || ':' || p_request_id
  );
  IF (v_credit->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'diamond_release_credit_failed:%', v_credit->>'error';
  END IF;

  ELSE
    SELECT jsonb_build_object('success',true,'new_balance',diamonds,
      'debt_settled',0,'transaction_id',NULL) INTO v_credit
      FROM public.profiles WHERE id=v_owner;
  END IF;

  IF COALESCE((v_credit->>'debt_settled')::bigint, 0) > 0 THEN
    SELECT id INTO v_debt_journal
      FROM public.diamond_transactions
     WHERE user_id = v_owner
       AND reference_id = 'debt-settlement:' || (v_credit->>'transaction_id')
       AND type = 'debt_settlement'
       AND amount = -(v_credit->>'debt_settled')::bigint;
    IF v_debt_journal IS NULL THEN
      RAISE EXCEPTION 'diamond_debt_journal_missing';
    END IF;

    PERFORM public.fn_ca_register_diamond_journal_row(v_debt_journal);
    IF NOT EXISTS (
      SELECT 1
        FROM public.ca_mint_ledger
       WHERE diamond_tx_id = v_debt_journal
         AND action = 'burn'
         AND asset = 'diamonds'
         AND holder_type = 'player'
         AND holder_id = v_owner
         AND amount = (v_credit->>'debt_settled')::bigint
    ) THEN
      RAISE EXCEPTION 'diamond_debt_retirement_missing';
    END IF;
  END IF;

  UPDATE public.poker_diamond_custody
     SET balance = 0,
         state = 'released',
         released_at = now()
   WHERE id = p_custody_id;

  v_receipt := jsonb_build_object(
    'success', true,
    'custody_id', p_custody_id,
    'request_id', p_request_id,
    'amount', v_c.balance,
    'available_balance', (v_credit->>'new_balance')::bigint,
    'custody_balance', 0,
    'debt_settled', (v_credit->>'debt_settled')::bigint,
    'journal_id', v_credit->>'transaction_id'
  );

  INSERT INTO public.poker_diamond_movements(
    request_id, custody_id, user_id, action, amount,
    source_account, destination_account, wallet_journal_id, request, receipt
  ) VALUES (
    p_request_id, p_custody_id, v_owner, 'release', v_c.balance,
    'arena_custody:' || p_custody_id, 'player:' || v_owner,
    (v_credit->>'transaction_id')::uuid, v_request, v_receipt
  );

  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_recognize_accounting_tournament_fees(p_tournament_id uuid, p_recognized_at timestamp with time zone, p_bank_club_id uuid, p_union_wallet_transaction_id uuid, p_bank_journal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE plan jsonb;prior record;source record;bank record;active_ids uuid[];refunded_ids uuid[];
 net_fee numeric;game_union uuid;rows_written int:=0;users_count int;source_count int;vip record;week_date date;batch_admitted boolean;
BEGIN
 IF p_recognized_at IS NULL OR p_recognized_at IS DISTINCT FROM transaction_timestamp() THEN
  RAISE EXCEPTION 'tournament_fee_original_recognition_transaction_required' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_recognition:'||p_tournament_id::text,0));
 PERFORM public.fn_lock_accounting_tournament_recognition_week(p_tournament_id,p_recognized_at);
 plan:=public.fn_accounting_tournament_fee_net_plan(p_tournament_id);
 SELECT * INTO prior FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=p_tournament_id;
 IF FOUND THEN
  IF prior.source_fingerprint IS DISTINCT FROM plan->>'source_fingerprint' THEN
   RAISE EXCEPTION 'recognized_tournament_fee_sources_changed' USING ERRCODE='23514'; END IF;
  RETURN prior.plan||jsonb_build_object('status',prior.status,'payable',prior.status='recognized','replayed',true,'recognized_at',prior.recognized_at);
 END IF;
 net_fee:=(plan->>'net_fee')::numeric;game_union:=NULLIF(plan->>'union_id','')::uuid;
 IF p_bank_club_id IS NULL AND net_fee>0 THEN RAISE EXCEPTION 'tournament_fee_bank_club_required' USING ERRCODE='23514'; END IF;
 PERFORM public.fn_accounting_tournament_bank_proof(p_tournament_id,p_recognized_at,p_bank_club_id,game_union,net_fee,p_union_wallet_transaction_id,p_bank_journal_id);
 SELECT COALESCE(array_agg(value::uuid),'{}') INTO active_ids FROM jsonb_array_elements_text(plan->'active_source_ids');
 SELECT COALESCE(array_agg(value::uuid),'{}') INTO refunded_ids FROM jsonb_array_elements_text(plan->'refunded_source_ids');
 INSERT INTO public.accounting_tournament_fee_recognitions(tournament_id,recognized_at,status,net_rake,union_id,bank_club_id,
  union_wallet_transaction_id,bank_journal_id,source_fingerprint,plan)
 VALUES(p_tournament_id,p_recognized_at,CASE WHEN net_fee>0 THEN 'recognized' ELSE 'cancelled' END,net_fee,game_union,p_bank_club_id,
  p_union_wallet_transaction_id,p_bank_journal_id,plan->>'source_fingerprint',plan);
 INSERT INTO public.accounting_tournament_recognized_sources(source_id,tournament_id,recognized_at,disposition,rake_credit)
 SELECT s.id,p_tournament_id,p_recognized_at,CASE WHEN s.id=ANY(active_ids) THEN 'earned' ELSE 'refunded' END,
  CASE WHEN s.id=ANY(active_ids) THEN s.rake_credit ELSE 0 END
 FROM public.accounting_tournament_fee_sources s WHERE s.id=ANY(active_ids||refunded_ids);
 -- Only the existing historical owner admission excludes concurrent commission
 -- writers. Ordinary recognitions retain their exact per-source write order.
 batch_admitted:=EXISTS(SELECT 1 FROM pg_locks l WHERE l.locktype='relation'
  AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
  AND l.relation='public.agent_commissions'::regclass AND l.pid=pg_backend_pid()
  AND l.granted AND l.mode IN('ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock'));
 -- Post the same recorded tiers in one statement. Row guards and the real
 -- transition-table rollups still run; repeated per-tier rollup writes do not.
 IF batch_admitted AND EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids)) THEN
  IF NOT public.fn_caller_is_engine() THEN
   RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  IF NOT isfinite(p_recognized_at) OR EXISTS(
   SELECT 1 FROM public.accounting_tournament_fee_sources s WHERE s.id=ANY(active_ids)
    AND jsonb_typeof(s.contract->'tiers') IS DISTINCT FROM 'array') THEN
   RAISE EXCEPTION 'invalid_accounting_commission_source' USING ERRCODE='22023'; END IF;
  -- Check every source, including an agreement with no payable tiers.
  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s
   JOIN public.agent_commission_settlements closed ON closed.club_id=(s.contract->>'club_id')::uuid
    AND p_recognized_at>=closed.period_start AND p_recognized_at<closed.period_end
   WHERE s.id=ANY(active_ids)) THEN
   RAISE EXCEPTION 'cash_accrual_closed_period_requires_adjustment' USING ERRCODE='23514'; END IF;
  -- Cash writers may hold a club key while waiting for our relation lock.
  -- Never wait back on them: refuse and roll back this whole owner operation.
  FOR source IN SELECT DISTINCT (s.contract->>'club_id')::uuid club_id
   FROM public.accounting_tournament_fee_sources s
   CROSS JOIN LATERAL jsonb_array_elements(s.contract->'tiers') tier(value)
   WHERE s.id=ANY(active_ids) AND (tier.value->>'amount')::numeric>0
   ORDER BY 1 LOOP
   IF NOT pg_try_advisory_xact_lock(hashtextextended('agent-commission:'||source.club_id::text,0)) THEN
    -- The payer retries 55P03 while retaining its outer locks. This admission
    -- refusal must propagate instead, releasing the complete owner transaction.
    RAISE EXCEPTION 'held_fee_commission_club_busy' USING ERRCODE='55000';
   END IF;
  END LOOP;
  INSERT INTO public.agent_commissions(club_id,user_id,amount,commission_rate,source_type,source_id,notes,created_at)
  SELECT (s.contract->>'club_id')::uuid,(tier.value->>'user_id')::uuid,
   (tier.value->>'amount')::numeric,(tier.value->>'rate')::numeric,
   'tournament_fee_accrual',s.id,
   'Commission from recorded earning agreement; tier '||(tier.value->>'depth'),p_recognized_at
  FROM public.accounting_tournament_fee_sources s
  CROSS JOIN LATERAL jsonb_array_elements(s.contract->'tiers') WITH ORDINALITY tier(value,ordinality)
  WHERE s.id=ANY(active_ids) AND (tier.value->>'amount')::numeric>0
  ORDER BY s.club_id,s.player_id,s.id,tier.ordinality;
  GET DIAGNOSTICS rows_written=ROW_COUNT;
  -- Counter credit belongs to EVERY tier, even a zero-commission tier.
  -- A retired/missing profile never suppresses its recorded user's liability.
  -- Preserve the old source/tier first-lock order before a grouped UPDATE.
  -- Zero-commission cash tiers also lock agents without a rollup row first.
  PERFORM a.id FROM public.accounting_tournament_fee_sources s
  CROSS JOIN LATERAL jsonb_array_elements(s.contract->'tiers') WITH ORDINALITY tier(value,ordinality)
  JOIN public.agents a ON a.id=(tier.value->>'agent_id')::uuid
   AND a.club_id=(s.contract->>'club_id')::uuid AND a.user_id=(tier.value->>'user_id')::uuid
  WHERE s.id=ANY(active_ids)
  ORDER BY s.club_id,s.player_id,s.id,tier.ordinality
  FOR NO KEY UPDATE OF a;
  UPDATE public.agents a SET
   lifetime_rake_generated=COALESCE(a.lifetime_rake_generated,0)+credits.rake_credit,
   weekly_rake_generated=COALESCE(a.weekly_rake_generated,0)+CASE
    WHEN public.fn_union_week_start(p_recognized_at)=public.fn_union_week_start(now())
    THEN credits.rake_credit ELSE 0 END,
   last_active_at=now(),updated_at=now()
  FROM (SELECT (tier.value->>'agent_id')::uuid agent_id,
    (s.contract->>'club_id')::uuid club_id,(tier.value->>'user_id')::uuid user_id,
    sum((s.contract->>'rake_credit')::numeric) rake_credit
   FROM public.accounting_tournament_fee_sources s
   CROSS JOIN LATERAL jsonb_array_elements(s.contract->'tiers') tier(value)
   WHERE s.id=ANY(active_ids)
   GROUP BY (tier.value->>'agent_id')::uuid,(s.contract->>'club_id')::uuid,(tier.value->>'user_id')::uuid) credits
  WHERE a.id=credits.agent_id AND a.club_id=credits.club_id AND a.user_id=credits.user_id;
 END IF;
 FOR source IN SELECT * FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids) ORDER BY club_id,player_id,id LOOP
  IF NOT batch_admitted THEN
   rows_written:=rows_written+public.fn_post_accounting_commission_source(source.id,'tournament_fee_accrual',p_recognized_at,source.contract);
  END IF;
  -- Statistics use the real source record/player pair. The source credit is
  -- recognized once; a retry is guarded by the terminal recognition row above.
  PERFORM public.apply_rakeback_player_stats(source.rake_record_id,source.player_id,source.club_id,0,source.rake_credit);
 END LOOP;
 -- VIP already has a unique event/player source key. Preserve its original
 -- settlement-time grouping while giving it exact conserved contributor cents.
 FOR vip IN SELECT player_id,sum(rake_credit) credit FROM public.accounting_tournament_fee_sources
  WHERE id=ANY(active_ids) GROUP BY player_id ORDER BY player_id LOOP
  IF vip.credit>0 THEN PERFORM public.fn_award_vip_credit(vip.player_id,vip.credit,'tournament_rake',p_tournament_id,'Tournament rake generated'); END IF;
 END LOOP;
 week_date:=(public.fn_union_week_start(p_recognized_at) AT TIME ZONE 'America/Los_Angeles')::date;
 INSERT INTO public.accounting_period_recompute_requests(club_id,period_start,period_end,status)
 SELECT DISTINCT club_id,week_date,week_date+6,'pending' FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids)
 ON CONFLICT(club_id,period_start,period_end) DO UPDATE SET status='pending',reason=NULL,last_result='{}'::jsonb,last_requested_at=transaction_timestamp();
 SELECT count(DISTINCT player_id),count(*) INTO users_count,source_count FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids);
 RETURN plan||jsonb_build_object('status',CASE WHEN net_fee>0 THEN 'recognized' ELSE 'cancelled' END,
  'recognized_at',p_recognized_at,'payable',net_fee>0,'replayed',false,'commission_rows',rows_written,
  'attributed_users',users_count,'source_count',source_count,'attributed_chips',net_fee);
END $function$

CREATE OR REPLACE FUNCTION public.fn_stamp_accounting_tournament_fee(p_rake_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.rake_records%ROWTYPE;t record;e record;tp record;item record;reserve_id uuid;
 manifest jsonb;contributors jsonb:='[]';game_union uuid;expected_entitlement text;
 expected_category text;uid uuid;reg uuid;count_rows int;cutoff timestamptz;legacy boolean:=false;
BEGIN
 SELECT * INTO r FROM public.rake_records WHERE id=p_rake_record_id FOR UPDATE;
 IF NOT FOUND OR NOT r.is_tournament OR r.rake_amount<=0 THEN
  RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id) THEN
  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id AND status='legacy_unverified') THEN
   RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
  END IF;
  RETURN public.fn_capture_accounting_tournament_fee(r.id);
 END IF;
 SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
 IF r.created_at IS DISTINCT FROM transaction_timestamp() OR cutoff IS NULL OR r.created_at<cutoff THEN
  RAISE EXCEPTION 'tournament_fee_not_captured_by_original_producer' USING ERRCODE='55000'; END IF;
 SELECT id,club_id,union_id,is_private,tournament_type INTO t FROM public.tournaments WHERE id=r.tournament_id FOR SHARE;
 IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
  RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 game_union:=CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
 IF r.source='fn_spin_book_entry' THEN
  IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3 THEN
   RAISE EXCEPTION 'spin_fee_exact_paid_contributors_required' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
   SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=item.player_id;
   IF NOT FOUND OR tp.club_id IS NULL THEN RAISE EXCEPTION 'spin_fee_entry_club_missing' USING ERRCODE='23514'; END IF;
   SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
   SELECT * INTO e FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   contributors:=contributors||jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
    'registration_id',tp.id,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',item.weight));
   legacy:=legacy OR e.created_at<cutoff;
  END LOOP;
  SELECT count(*) INTO count_rows FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
  IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_reserve_required' USING ERRCODE='23514'; END IF;
  SELECT id INTO reserve_id FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
 ELSE
  IF NOT COALESCE(r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false) THEN
   RAISE EXCEPTION 'tournament_fee_exact_player_required' USING ERRCODE='23514'; END IF;
  uid:=(r.metadata->>'user_id')::uuid;
  expected_entitlement:=CASE r.source WHEN 'fn_register_for_tournament' THEN 'wallet_charge'
   WHEN 'fn_register_horse_for_tournament' THEN 'wallet_charge' WHEN 'process_tournament_rebuy' THEN 'wallet_charge'
   WHEN 'fn_award_satellite_seat' THEN 'satellite_seat' WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket' END;
  expected_category:=CASE WHEN r.source='process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
  IF expected_entitlement IS NULL THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE='55000'; END IF;
  reg:=NULLIF(r.metadata->>'registration_id','')::uuid;
  IF reg IS NULL AND r.source='process_tournament_rebuy' THEN
   SELECT id INTO reg FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=uid;
  END IF;
  IF reg IS NULL THEN RAISE EXCEPTION 'tournament_fee_exact_registration_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  IF count_rows<>1 THEN RAISE EXCEPTION 'tournament_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  contributors:=jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
   'registration_id',reg,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',r.rake_amount));
 END IF;
 IF legacy THEN
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified');
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
 END IF;
 manifest:=jsonb_build_object('union_id',game_union,'game_type',lower(t.tournament_type),'contributors',contributors,'spin_reserve_id',reserve_id);
 -- Original tournament evidence may already be sealed by a satellite receipt.
 -- Capture its manifest on the accounting batch; never rewrite that raw row.
 BEGIN
  RETURN public.fn_capture_accounting_tournament_fee(r.id,manifest);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  -- Missing observed agreement may not destroy a proved original fee charge.
  -- This subtransaction rolls back every contributor receipt before recording
  -- the entire batch as unavailable. No partial commission can become payable.
  IF SQLERRM NOT IN('accounting_terms_not_observed','accounting_terms_not_active') THEN RAISE; END IF;
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status,source_manifest)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified',
    manifest||jsonb_build_object('capture_reason',SQLERRM));
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false,'reason',SQLERRM);
 END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_tournament_entry_split(p_buy_in numeric, p_fee numeric, p_bounty numeric, p_is_bounty boolean)
 RETURNS TABLE(charge numeric, rake numeric, bounty numeric, prize numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_charge numeric; v_rake numeric; v_bounty numeric; v_prize numeric;
BEGIN
  IF NOT COALESCE(p_is_bounty, false) THEN
    -- Non-bounty: unchanged - fee charged on top of the buy-in portion.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := 0;
    v_prize  := round(COALESCE(p_buy_in,0),2);
  ELSE
    -- Bounty event: the rake is exactly the fee. A zero fee is a legitimate
    -- outcome of the whole-number floor rule (totals under 10 take no rake)
    -- and must NEVER be replaced with a percentage default.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := round(COALESCE(p_bounty,0), 2);
    v_prize  := round(v_charge - v_rake - v_bounty, 2);  -- = buy_in - bounty
  END IF;
  RETURN QUERY SELECT v_charge, v_rake, v_bounty, v_prize;
END;
$function$
